(function () {
  'use strict';

  var domains = window.CPACC_DOMAINS;
  var questions = [];
  var answerKey = 0;
  var sources = {
    iaapSample: {
      title: 'IAAP CPACC Sample Exam Questions',
      year: 'IAAP reference',
      scope: 'Official sample items consulted for scope and format only; no question wording is reproduced.',
      url: 'https://www.accessibilityassociation.org/cpacc-sample-exam-questions'
    },
    iaapOutline: {
      title: 'IAAP CPACC Certification Content Outline',
      year: 'IAAP reference',
      scope: 'Official outline of CPACC knowledge areas and exam scope.',
      url: 'https://www.accessibilityassociation.org/cpacc-certification-content-outline'
    },
    iaapBok: {
      title: 'IAAP CPACC Body of Knowledge, October 2023',
      year: 2023,
      scope: 'CPACC competencies across disability, accessibility and universal design, and standards and management.',
      url: 'https://www.accessibilityassociation.org/sfsites/c/resource/CPACCBoK'
    }
  };

  function add(domainIndex, topic, sourceId, rows) {
    rows.forEach(function (row) {
      var answer = answerKey % 4;
      var options = row.distractors.slice();
      options.splice(answer, 0, row.correct);
      questions.push({
        id: 'expanded-' + String(questions.length + 1).padStart(3, '0'),
        domain: domains[domainIndex],
        topic: topic,
        difficulty: row.level,
        type: row.type,
        prompt: row.prompt,
        options: options,
        answer: answer,
        explanation: row.explanation,
        sourceId: 'iaapBok',
        sourceSection: row.section
      });
      answerKey += 1;
    });
  }

  add(0, 'Models of disability and participation', 'iaap', [
    { level: 'Foundational', type: 'concept', section: 'Disability models', prompt: 'A public building has only stairs at its entrance. Which interpretation best reflects the social model of disability?', correct: 'The built environment creates a barrier to participation for some people.', distractors: ['An individual impairment alone explains every access outcome.', 'A person must change their body before the building can be used.', 'Disability is unrelated to the design of environments.'], explanation: 'The social model directs attention to social and environmental barriers that restrict participation.' },
    { level: 'Intermediate', type: 'scenario', section: 'Interactional perspectives', prompt: 'A person who uses a wheelchair can enter a venue but cannot reach the ticket counter. What is the most useful interactional analysis?', correct: 'Consider the person, the task, and the counter and service environment together.', distractors: ['Classify the person by diagnosis and stop there.', 'Assume the entrance ramp resolved every access issue.', 'Treat the counter height as unrelated to participation.'], explanation: 'Interactional perspectives consider how a person, activity, and environment combine to enable or constrain participation.' },
    { level: 'Foundational', type: 'concept', section: 'Disability models', prompt: 'Which statement most accurately distinguishes impairment from disability?', correct: 'Impairment concerns body function or structure; disability can also involve contextual barriers and participation.', distractors: ['The terms always mean exactly the same thing.', 'Disability is exclusively an equipment failure.', 'Impairment describes only a legal accommodation.'], explanation: 'The terms are related but not interchangeable; disability is also shaped by context and barriers.' },
    { level: 'Intermediate', type: 'application', section: 'Disability models', prompt: 'A team is mapping barriers in an online appointment service. Which question best complements an individual-focused clinical description?', correct: 'Which features of the service prevent people from completing the appointment task?', distractors: ['Which users should be excluded from the service?', 'How can the team require every user to use the same device?', 'Which diagnosis should be treated as the only user need?'], explanation: 'Barrier-focused inquiry identifies changes to the service and environment rather than locating the whole problem in a user.' },
    { level: 'Foundational', type: 'concept', section: 'Disability and participation', prompt: 'What does a rights-based approach to disability primarily emphasize?', correct: 'Equal rights, dignity, participation, and removal of barriers.', distractors: ['Charity as a substitute for legal rights.', 'Separate participation as the default.', 'A requirement that people disclose diagnoses to access services.'], explanation: 'A rights-based approach centers equal enjoyment of rights and meaningful participation.' },
    { level: 'Advanced', type: 'scenario', section: 'Disability models', prompt: 'An organization adds a ramp but leaves its event registration form unusable by keyboard. What does this illustrate?', correct: 'Accessibility is multidimensional; removing one barrier does not resolve others.', distractors: ['A physical accommodation guarantees digital access.', 'Digital access is unrelated to event participation.', 'The organization can stop evaluating access after one improvement.'], explanation: 'Access barriers can occur in distinct parts of a service and should be assessed across the full experience.' },
    { level: 'Intermediate', type: 'concept', section: 'Disability and participation', prompt: 'Why is participation by people with disabilities important when defining an accessibility problem?', correct: 'Their experience helps expose barriers and challenge assumptions about how a service is used.', distractors: ['It transfers the organization’s responsibility to participants.', 'One participant can represent every disability and preference.', 'It removes the need to evaluate applicable standards.'], explanation: 'Meaningful participation improves understanding but does not replace an organization’s responsibility or other evaluation methods.' },
    { level: 'Foundational', type: 'application', section: 'Disability models', prompt: 'Which approach avoids treating a disability category as a complete description of a person?', correct: 'Ask about the person’s goals, context, and preferences instead of assuming them.', distractors: ['Use the same accommodation for everyone with the label.', 'Infer technical ability from a diagnosis.', 'Design only for the most common presentation.'], explanation: 'People with the same label may have different abilities, contexts, tools, and preferences.' }
  ]);

  add(0, 'Functional access needs and intersectionality', 'iaap', [
    { level: 'Foundational', type: 'concept', section: 'Sensory access', prompt: 'A user cannot distinguish two status colors. What change most directly makes the status perceivable without relying on color alone?', correct: 'Add a text label or another meaningful visual cue.', distractors: ['Choose two more saturated colors only.', 'Move the colors farther apart in a legend.', 'Announce the status only with a sound.'], explanation: 'Redundant cues such as text labels help people who do not perceive a color distinction and users in other contexts.' },
    { level: 'Intermediate', type: 'scenario', section: 'Cognitive access', prompt: 'A service times out while a user is reading a long instruction. Which design response is most helpful?', correct: 'Give a warning and a way to extend or control the time limit when feasible.', distractors: ['Shorten the warning until it is difficult to read.', 'Reset the form without explanation.', 'Require users to finish at a fixed speed.'], explanation: 'Controllable timing can help users who need more time to read, think, or operate controls.' },
    { level: 'Foundational', type: 'concept', section: 'Hearing access', prompt: 'Which is a suitable way to provide access to spoken information in prerecorded video?', correct: 'Accurate synchronized captions.', distractors: ['A transcript icon with no transcript.', 'A louder soundtrack only.', 'A visual progress bar.'], explanation: 'Captions make speech and relevant audio information available as synchronized text.' },
    { level: 'Intermediate', type: 'application', section: 'Vision access', prompt: 'A chart communicates several trends using color alone. What is the strongest complementary alternative?', correct: 'Provide text or tabular information that conveys the chart’s important relationships.', distractors: ['Add a note that the colors are different.', 'Use a larger chart with the same color-only encoding.', 'Describe the chart only by its file name.'], explanation: 'An equivalent should communicate the information, not merely identify the image or its colors.' },
    { level: 'Foundational', type: 'concept', section: 'Motor access', prompt: 'Which input method may help someone who cannot use a conventional pointer?', correct: 'Keyboard, switch, voice, or another suitable alternative input method.', distractors: ['A hover-only pointer gesture.', 'A smaller pointer target.', 'A required rapid double-click.'], explanation: 'Alternative input methods vary; interfaces should not depend exclusively on precise pointer movement.' },
    { level: 'Intermediate', type: 'scenario', section: 'Cognitive access', prompt: 'Users report losing their place in a multi-step task. Which improvement is most likely to help?', correct: 'Use clear step headings, indicate progress, and preserve entered information.', distractors: ['Change the layout and labels on each step.', 'Remove all instructions to reduce page length.', 'Hide errors until the last step.'], explanation: 'Predictable structure, progress cues, and preserved input reduce avoidable memory and navigation demands.' },
    { level: 'Advanced', type: 'application', section: 'Intersectionality', prompt: 'Why should a team avoid designing for a single assumed “typical” user with a disability?', correct: 'People’s access needs and experiences vary and can be shaped by intersecting identities and contexts.', distractors: ['Accessibility needs are identical within each category.', 'Intersectionality applies only to visual design.', 'A single persona makes user research unnecessary.'], explanation: 'Disability does not erase other identities or contextual factors, and one user cannot represent everyone.' },
    { level: 'Foundational', type: 'concept', section: 'Deafness and communication', prompt: 'Which statement about Deaf people and communication is most accurate?', correct: 'People differ; some use signed languages, some use speech or text, and some use multiple methods.', distractors: ['Every Deaf person uses the same signed language.', 'Captions are unnecessary if a video has sound.', 'Deafness implies a preference for written English.'], explanation: 'Deaf and hard-of-hearing people are diverse, and communication preferences should not be assumed.' },
    { level: 'Intermediate', type: 'scenario', section: 'Temporary and situational access', prompt: 'A parent is holding a child and cannot use one hand to operate a mobile service. What does this example show?', correct: 'A situational constraint can create an access need even without a permanent impairment.', distractors: ['Only permanent disabilities need accessible design.', 'One-handed use is relevant only to desktop devices.', 'The service should require a second person.'], explanation: 'Situational limitations can make flexible, one-handed interaction useful to many people.' }
  ]);

  add(0, 'Assistive technology and alternative communication', 'iaap', [
    { level: 'Foundational', type: 'concept', section: 'Assistive technology', prompt: 'What is a screen reader primarily designed to do?', correct: 'Present interface content and structure through speech, braille, or both.', distractors: ['Magnify every pixel without changing output.', 'Translate every page into sign language.', 'Correct inaccessible markup automatically.'], explanation: 'Screen readers expose digital content through speech output, refreshable braille, or both.' },
    { level: 'Intermediate', type: 'scenario', section: 'Assistive technology', prompt: 'A custom web control is announced only as “button” with no useful name. Which information is most clearly missing?', correct: 'An accessible name that identifies the control’s purpose.', distractors: ['A larger source-code file.', 'A different mouse cursor.', 'A caption track.'], explanation: 'Assistive technologies need the component’s name, role, and state; an informative accessible name identifies its purpose.' },
    { level: 'Foundational', type: 'concept', section: 'Assistive technology', prompt: 'What does a refreshable braille display provide?', correct: 'Tactile braille output whose cells update as digital text changes.', distractors: ['A printed copy of every webpage.', 'Speech recognition for spoken commands.', 'A magnified visual version of text.'], explanation: 'Refreshable braille displays use changeable cells to present computer or mobile-device text tactually.' },
    { level: 'Intermediate', type: 'application', section: 'Alternative input', prompt: 'How does switch scanning commonly allow a user to select an item?', correct: 'The interface moves among choices and the user activates a switch at the desired choice.', distractors: ['The user must hold two keys and drag simultaneously.', 'The device reads only printed braille.', 'The user selects items by distinguishing color alone.'], explanation: 'Scanning presents selectable targets in sequence for activation with one or more switches.' },
    { level: 'Foundational', type: 'concept', section: 'Assistive technology', prompt: 'What is augmentative and alternative communication (AAC)?', correct: 'Methods and tools that supplement or provide alternatives to spoken communication.', distractors: ['A technique for enlarging screen text.', 'A standard for web page headings.', 'A device used only to control a mouse.'], explanation: 'AAC includes communication methods ranging from gestures and boards to speech-generating tools.' },
    { level: 'Intermediate', type: 'scenario', section: 'Assistive technology interoperability', prompt: 'A site works with one screen reader but not another. What is the best next step?', correct: 'Check semantic structure and accessibility API behavior, then test with relevant combinations.', distractors: ['Require every user to install the same screen reader.', 'Remove labels to simplify the page.', 'Conclude that no assistive technology can work.'], explanation: 'Assistive technologies and platforms vary; standards-based semantics and representative testing improve interoperability.' },
    { level: 'Advanced', type: 'application', section: 'Assistive technology interoperability', prompt: 'Why can replacing a native checkbox with an unlabelled clickable icon create a barrier?', correct: 'It may lose expected keyboard behavior, programmatic role, state, and accessible name.', distractors: ['Native controls cannot be used on mobile devices.', 'Icons are always inaccessible regardless of implementation.', 'A checkbox must be a picture to work with assistive technology.'], explanation: 'Custom controls must recreate semantics and interaction behavior; native HTML supplies much of this automatically.' },
    { level: 'Foundational', type: 'concept', section: 'Voice input', prompt: 'Which design feature can support people using speech recognition to activate controls?', correct: 'Visible labels that match or clearly contain the controls’ accessible names.', distractors: ['Controls with no visible text.', 'Instructions that require mouse hovering.', 'Text labels that change unexpectedly.'], explanation: 'Matching visible and accessible names helps voice-control users identify and activate interface elements.' },
    { level: 'Intermediate', type: 'scenario', section: 'Magnification', prompt: 'A magnification user sees only a small portion of a page at once. Which design practice helps them keep context?', correct: 'Keep headings, focus order, and navigation predictable and avoid horizontal content traps.', distractors: ['Place important instructions only at the far edge of a wide table.', 'Move focus to the page top after each action.', 'Use fixed-width content that clips when zoomed.'], explanation: 'Predictability and reflow help users who view only a magnified portion of the interface.' }
  ]);

  add(0, 'Inclusive communication and accessible content', 'iaap', [
    { level: 'Foundational', type: 'concept', section: 'Accessible media', prompt: 'What does audio description add to video?', correct: 'Narration of important visual information that is not conveyed by the soundtrack.', distractors: ['Synchronized captions for dialogue only.', 'A transcript of unrelated background music.', 'A longer video title.'], explanation: 'Audio description conveys relevant visual details such as actions, settings, and on-screen text.' },
    { level: 'Intermediate', type: 'scenario', section: 'Accessible media', prompt: 'A training video contains meaningful sound effects but no dialogue. What should captions do?', correct: 'Identify relevant non-speech audio as well as any speech that occurs.', distractors: ['Omit the sound effects because there is no dialogue.', 'Repeat only the video title.', 'Show captions after the video ends.'], explanation: 'Captions represent speech and relevant non-speech audio in synchronization with media.' },
    { level: 'Foundational', type: 'application', section: 'Language and readability', prompt: 'Which writing choice is most likely to reduce avoidable language-processing effort?', correct: 'Use clear, direct language and explain necessary specialized terms.', distractors: ['Use unexplained abbreviations throughout.', 'Put essential instructions in dense blocks of all-capital text.', 'Use metaphors for every procedural step.'], explanation: 'Clear language and explanations can improve comprehension for many readers without oversimplifying essential content.' },
    { level: 'Advanced', type: 'scenario', section: 'Accessible communication', prompt: 'A user cannot complete a voice-only identity check. What is the most inclusive service response?', correct: 'Offer an equivalent accessible verification route that does not require speech.', distractors: ['Ask the user to find someone else to speak.', 'Treat the user as having failed identity verification.', 'Remove all verification for every customer.'], explanation: 'A non-voice alternative preserves the service goal without making speech ability a prerequisite.' },
    { level: 'Foundational', type: 'concept', section: 'Language and identity', prompt: 'Which statement about person-first and identity-first language is best practice?', correct: 'Preferences differ, so use a person’s stated preference when known.', distractors: ['One form is universally preferred by all disabled people.', 'Language preference can be inferred from diagnosis.', 'Avoid asking or listening to the person.'], explanation: 'Both person-first and identity-first language are used; respect individual and community preferences.' },
    { level: 'Intermediate', type: 'application', section: 'Accessible communication', prompt: 'An alert is conveyed by a brief tone alone. What change gives access to users who cannot hear it?', correct: 'Provide a perceivable visual or textual alert that communicates the same information.', distractors: ['Make the tone shorter.', 'Play two tones instead of one.', 'Move the tone to a different speaker.'], explanation: 'Important information should not depend solely on a single sensory channel.' },
    { level: 'Foundational', type: 'concept', section: 'Accessible documents', prompt: 'Why should meaningful document headings be marked with semantic heading styles?', correct: 'They communicate structure and support navigation by assistive technology.', distractors: ['They guarantee every paragraph is concise.', 'They replace the document title.', 'They are used only to select font size.'], explanation: 'Semantic headings expose document organization and make section navigation easier.' },
    { level: 'Intermediate', type: 'scenario', section: 'Accessible communication', prompt: 'A public-service announcement is delivered only through a loudspeaker in a noisy station. Which alternative is most helpful?', correct: 'Provide the announcement through a visible text channel as well.', distractors: ['Repeat it at the same volume only.', 'Use a longer chime before it.', 'Ask travelers to listen more carefully.'], explanation: 'A text-based channel provides equivalent access when audio is unavailable or difficult to perceive.' }
  ]);

  add(0, 'Fluctuating access needs and lived experience', 'iaap', [
    { level: 'Foundational', type: 'concept', section: 'Disability and context', prompt: 'Why should an interface account for fatigue and fluctuating ability?', correct: 'A person’s energy, pain, concentration, or functional ability may vary over time.', distractors: ['Every disability has a fixed effect throughout the day.', 'Fatigue affects only users of mobile devices.', 'Flexible interaction makes instructions unnecessary.'], explanation: 'Flexible pacing and persistent progress can help when a person’s abilities or energy change.' },
    { level: 'Intermediate', type: 'scenario', section: 'Disability and context', prompt: 'A person with chronic pain needs to pause a long application and return later. Which design choice best supports them?', correct: 'Save progress and allow the person to resume without losing entered information.', distractors: ['Require the form to be completed in one session.', 'Clear the form whenever the page is left.', 'Use a short automatic timeout with no warning.'], explanation: 'Saving progress reduces avoidable physical and cognitive effort and supports variable stamina.' },
    { level: 'Foundational', type: 'concept', section: 'Disability and context', prompt: 'What does the term “invisible disability” generally describe?', correct: 'A disability that may not be apparent to others from a person’s outward appearance.', distractors: ['A disability that cannot affect digital access.', 'A condition that never requires accommodation.', 'An impairment that is necessarily temporary.'], explanation: 'Many disabilities are not immediately visible, so access needs should not be judged by appearance.' },
    { level: 'Intermediate', type: 'application', section: 'Disability and context', prompt: 'A person has an episodic condition with periods of greater and lesser impact. What is a sound design assumption?', correct: 'Needs can change, so provide flexible ways to complete and resume tasks.', distractors: ['Access is needed only on the day a diagnosis is made.', 'Every interaction should have a fixed time limit.', 'A person’s needs can be inferred from a single visit.'], explanation: 'Some conditions are episodic; flexible systems are more resilient to changes in functional impact.' },
    { level: 'Foundational', type: 'concept', section: 'Disability and context', prompt: 'What is a useful principle for accommodating people with chronic pain?', correct: 'Reduce unnecessary effort and allow users to control pacing when possible.', distractors: ['Require repeated precision gestures.', 'Use flashing alerts to demand quick action.', 'Assume the same accommodation works for everyone.'], explanation: 'Reducing effort and giving users control can support varied pain and energy levels.' },
    { level: 'Intermediate', type: 'scenario', section: 'Deafblindness', prompt: 'A service assumes every user can simultaneously listen to audio and view a screen. What access need may this overlook?', correct: 'A person who is deafblind may rely on tactile output such as a braille display.', distractors: ['A user with a standard mouse.', 'A person who prefers a larger pointer.', 'A user who needs only a printed receipt.'], explanation: 'People who are deafblind may use combined assistive technologies, including refreshable braille.' },
    { level: 'Foundational', type: 'application', section: 'Neurodiversity', prompt: 'A user reports that flashing transitions are distracting and uncomfortable. What is a respectful design response?', correct: 'Avoid unnecessary motion and support the user’s reduced-motion preference.', distractors: ['Require the user to finish before the animation ends.', 'Make all information available only during transitions.', 'Assume all neurodivergent people share the same preference.'], explanation: 'Motion preferences vary; reducing nonessential animation supports user comfort without stereotyping.' },
    { level: 'Intermediate', type: 'concept', section: 'Disability and context', prompt: 'Why can a person’s environment change whether an impairment creates a participation barrier?', correct: 'Tools, design, support, and context can remove or introduce barriers for a given task.', distractors: ['The environment has no effect once an impairment exists.', 'Every environment creates an identical barrier.', 'A person’s diagnosis determines all environmental outcomes.'], explanation: 'Disability and participation are shaped through interaction between people and their environments.' },
    { level: 'Advanced', type: 'scenario', section: 'Disability and context', prompt: 'A team’s “accessibility persona” combines several diagnoses into one stereotyped profile. What is the best corrective action?', correct: 'Use research with diverse participants and treat personas as limited design aids, not substitutes for individuals.', distractors: ['Use the persona as the sole source of requirements.', 'Assume the profile represents every person with a disability.', 'Remove disabled participants from later research.'], explanation: 'Personas can help teams discuss needs, but they should not replace diverse evidence or imply a single lived experience.' }
  ]);

  add(1, 'Universal design and inclusive design', 'ud', [
    { level: 'Foundational', type: 'concept', section: 'Universal design principles', prompt: 'Which is one of the seven Principles of Universal Design?', correct: 'Tolerance for error.', distractors: ['Mandatory complexity.', 'Single sensory channel.', 'Uniform physical effort.'], explanation: 'Tolerance for error is one of the seven principles, along with equitable use, flexibility, and others.' },
    { level: 'Intermediate', type: 'scenario', section: 'Universal design principles', prompt: 'A device can be operated with either hand and through touch or voice. Which universal design principle is most directly reflected?', correct: 'Flexibility in use.', distractors: ['Low physical effort only.', 'Size and space for approach and use only.', 'Tolerance for error only.'], explanation: 'Flexibility in use accommodates a range of preferences and abilities, including different input methods.' },
    { level: 'Foundational', type: 'application', section: 'Universal design principles', prompt: 'A form asks users to confirm before permanently deleting their work. Which principle does this most directly support?', correct: 'Tolerance for error.', distractors: ['Equitable use.', 'Perceptible information.', 'Size and space for approach and use.'], explanation: 'A confirmation step can reduce adverse consequences of an accidental action.' },
    { level: 'Intermediate', type: 'concept', section: 'Universal and inclusive design', prompt: 'How are universal design and accessibility accommodations best understood together?', correct: 'Broadly usable design can reduce barriers, while individual accommodations may still be needed.', distractors: ['Universal design makes all accommodations unnecessary.', 'Accommodations and inclusive design cannot coexist.', 'Universal design applies only to buildings.'], explanation: 'Universal design supports broad usability but does not eliminate the need for individual accommodations.' },
    { level: 'Advanced', type: 'scenario', section: 'Inclusive design practice', prompt: 'A team invites disabled participants only after all design decisions are final. What is the main limitation?', correct: 'Participants have little opportunity to influence assumptions and shape design choices early.', distractors: ['Late testing is always more representative.', 'Participation removes the need for a design process.', 'People with disabilities should participate only after launch.'], explanation: 'Involving people early and throughout design can influence the problem definition and proposed solutions.' },
    { level: 'Foundational', type: 'concept', section: 'Universal design principles', prompt: 'Which principle focuses on providing information effectively despite ambient conditions or sensory abilities?', correct: 'Perceptible information.', distractors: ['Low physical effort.', 'Equitable use.', 'Tolerance for error.'], explanation: 'Perceptible information is a universal design principle about communicating necessary information effectively.' },
    { level: 'Intermediate', type: 'application', section: 'Universal design principles', prompt: 'A control can be used comfortably without sustained force. Which principle is most directly relevant?', correct: 'Low physical effort.', distractors: ['Simple and intuitive use.', 'Equitable use.', 'Perceptible information.'], explanation: 'Low physical effort aims for efficient, comfortable use with minimal fatigue.' },
    { level: 'Foundational', type: 'scenario', section: 'Universal design principles', prompt: 'A kiosk provides room for a seated user to approach and reach its controls. Which principle is most directly addressed?', correct: 'Size and space for approach and use.', distractors: ['Tolerance for error.', 'Simple and intuitive use.', 'Perceptible information.'], explanation: 'The principle addresses appropriate reach, manipulation, and space regardless of body size, posture, or mobility.' }
  ]);

  add(1, 'WCAG principles and conformance', 'wcag', [
    { level: 'Foundational', type: 'concept', section: 'WCAG principles', prompt: 'What does the WCAG principle “Perceivable” require?', correct: 'Information and user-interface components must be presentable in ways users can perceive.', distractors: ['Every interaction must use a mouse.', 'The page must never update.', 'All content must use one font size.'], explanation: 'Perceivable information is available through sensory modalities users can access, with alternatives where needed.' },
    { level: 'Foundational', type: 'concept', section: 'WCAG principles', prompt: 'Which WCAG principle is most directly concerned with keyboard operability?', correct: 'Operable.', distractors: ['Perceivable.', 'Understandable.', 'Robust.'], explanation: 'Operable covers interaction and navigation, including making functionality available through a keyboard interface.' },
    { level: 'Intermediate', type: 'application', section: 'WCAG principles', prompt: 'A checkout changes navigation labels on each page and gives unclear errors. Which WCAG principle is most directly implicated?', correct: 'Understandable.', distractors: ['Perceivable.', 'Robust.', 'Operable only.'], explanation: 'Predictable operation, clear instructions, and helpful error identification support understandability.' },
    { level: 'Foundational', type: 'concept', section: 'WCAG principles', prompt: 'What does the WCAG principle “Robust” emphasize?', correct: 'Compatibility with a wide variety of user agents, including assistive technologies.', distractors: ['Use of a single browser.', 'Visual consistency between all websites.', 'Avoiding semantic markup.'], explanation: 'Robust content should work with current and future user agents, including assistive technologies.' },
    { level: 'Intermediate', type: 'concept', section: 'WCAG conformance', prompt: 'What is the relationship between WCAG Level AA and Level A criteria?', correct: 'AA conformance includes meeting the applicable Level A and Level AA success criteria.', distractors: ['AA replaces the Level A criteria.', 'Level A is a testing method, not a conformance level.', 'AA conformance requires only Level AAA criteria.'], explanation: 'WCAG conformance at a level includes the applicable criteria at that level and lower levels.' },
    { level: 'Advanced', type: 'application', section: 'WCAG conformance', prompt: 'A vendor says “our product is WCAG certified” but gives no standard version, scope, or evaluation evidence. What is the best response?', correct: 'Request a precise, scoped conformance claim and supporting evaluation details.', distractors: ['Assume WCAG issues a universal product certification.', 'Treat the claim as proof that all user tasks are accessible.', 'Assume the product meets every law worldwide.'], explanation: 'WCAG does not itself certify every product; a credible claim identifies its scope and standard version.' },
    { level: 'Foundational', type: 'concept', section: 'WCAG structure', prompt: 'What is a WCAG success criterion?', correct: 'A testable requirement addressing a specific aspect of accessibility.', distractors: ['A browser compatibility list.', 'An accessibility training certificate.', 'A legal opinion for every jurisdiction.'], explanation: 'Success criteria are the testable requirements used to evaluate aspects of web accessibility.' },
    { level: 'Intermediate', type: 'scenario', section: 'WCAG conformance', prompt: 'A page meets the criteria a team checked but fails another applicable Level A criterion. Can it claim Level AA conformance?', correct: 'No; all applicable Level A and AA criteria must be met for a Level AA conformance claim.', distractors: ['Yes, if most Level AA checks passed.', 'Yes, if an automated tool found no other errors.', 'Yes, because Level A criteria are optional at Level AA.'], explanation: 'A conformance level requires meeting all applicable success criteria at that level and below, not merely a subset.' },
    { level: 'Foundational', type: 'concept', section: 'WCAG structure', prompt: 'What does POUR stand for in WCAG?', correct: 'Perceivable, Operable, Understandable, Robust.', distractors: ['Practical, Organized, Usable, Responsive.', 'Perceptual, Observable, Universal, Readable.', 'Programmatic, Optional, Updated, Reliable.'], explanation: 'POUR summarizes the four WCAG principles.' },
    { level: 'Advanced', type: 'application', section: 'WCAG conformance', prompt: 'Why should an accessibility conformance claim identify the evaluated scope?', correct: 'A result for selected pages or states does not automatically establish conformance for all content and processes.', distractors: ['Scope matters only for printed documents.', 'A single tested page represents all user journeys.', 'Scope details are prohibited in conformance claims.'], explanation: 'WCAG conformance has defined scope requirements; a claim should not overstate what was evaluated.' }
  ]);

  add(1, 'Perceivable content and sensory alternatives', 'wcag', [
    { level: 'Foundational', type: 'application', section: 'Text alternatives', prompt: 'A decorative divider image adds no information. What text alternative is generally appropriate?', correct: 'An empty alternative so assistive technology can ignore it.', distractors: ['A long description of its colors.', 'The file name repeated as a label.', 'The word “image” in the alternative.'], explanation: 'A null alternative prevents decorative imagery from adding noise to the reading experience.' },
    { level: 'Intermediate', type: 'scenario', section: 'Text alternatives', prompt: 'A product image conveys a specific model and color needed to choose an item. What should its text alternative do?', correct: 'Convey the image’s relevant identifying information in context.', distractors: ['Say only “photo.”', 'Describe unrelated background details.', 'Be empty even though the image conveys information.'], explanation: 'Alternative text should convey the image’s purpose and relevant information in its context.' },
    { level: 'Advanced', type: 'application', section: 'Text alternatives', prompt: 'A complex chart contains trends and comparisons. Which approach provides the strongest equivalent?', correct: 'Give the graphic a concise identifying alternative and provide the data or relationships in nearby text or a table.', distractors: ['Use an empty alternative and no explanation.', 'List the chart colors only.', 'Repeat the caption “results” as the entire description.'], explanation: 'Complex images often need both a concise name and a longer equivalent that communicates their information.' },
    { level: 'Foundational', type: 'concept', section: 'Media alternatives', prompt: 'Which statement distinguishes captions from a transcript?', correct: 'Captions are synchronized with media; a transcript is a separate text version.', distractors: ['Transcripts must always be synchronized word-by-word.', 'Captions contain no audio information.', 'A transcript is a visual description of video only.'], explanation: 'Captions are time-aligned text; transcripts can be read separately and may be easier to scan.' },
    { level: 'Intermediate', type: 'scenario', section: 'Contrast and color', prompt: 'A chart uses red and green lines with no labels or patterns. What is the main access concern?', correct: 'Some users may not distinguish the lines, and the color alone does not communicate their identity robustly.', distractors: ['Charts must use only grayscale.', 'Red and green cannot be displayed by browsers.', 'The chart has too many semantic labels.'], explanation: 'Do not rely on color alone; labels, patterns, or other visual cues provide redundant identification.' },
    { level: 'Intermediate', type: 'application', section: 'Text resizing and reflow', prompt: 'What should happen when a user zooms in on typical page content?', correct: 'Content and functionality should remain available without unnecessary two-dimensional scrolling.', distractors: ['The page should lock at its original scale.', 'Text should be replaced by images.', 'The user should lose access to side content.'], explanation: 'WCAG reflow and resize requirements help users enlarge content without loss of information or functionality.' },
    { level: 'Foundational', type: 'concept', section: 'Audio alternatives', prompt: 'What does a text transcript of an audio-only recording provide?', correct: 'A text alternative for the information conveyed in the audio.', distractors: ['A replacement for keyboard access.', 'A guarantee that the audio is understandable.', 'A description of unrelated page structure.'], explanation: 'A transcript makes audio information available in text to people who cannot hear or prefer reading.' },
    { level: 'Advanced', type: 'scenario', section: 'Structure and meaning', prompt: 'A status update is exposed visually but is not announced when it changes. What kind of information may be missing programmatically?', correct: 'The change may not be exposed as a status message to assistive technology.', distractors: ['The page title must always be repeated.', 'Every update must move keyboard focus.', 'The status must be converted to an image.'], explanation: 'Programmatically determinable status changes can be announced without forcing users to search for them.' }
  ]);

  add(1, 'Operable interaction and navigation', 'wcag', [
    { level: 'Foundational', type: 'scenario', section: 'Keyboard access', prompt: 'A menu opens only when a user hovers a mouse over it. Which improvement is essential?', correct: 'Make the menu’s functionality available through keyboard interaction as well.', distractors: ['Use a brighter hover color.', 'Increase the mouse pointer size.', 'Add more hover-only submenus.'], explanation: 'Functionality should not depend on a pointer and hover; keyboard operation is a core operability need.' },
    { level: 'Intermediate', type: 'application', section: 'Keyboard access', prompt: 'A keyboard user enters a modal dialog but cannot reach the close button or leave the dialog. What is the key failure?', correct: 'Keyboard focus is not being managed so the dialog can be operated and exited.', distractors: ['The dialog has too much contrast.', 'The dialog uses a semantic heading.', 'The page has a skip link.'], explanation: 'A modal should support keyboard operation and provide a predictable way to close or exit it.' },
    { level: 'Foundational', type: 'concept', section: 'Focus visibility', prompt: 'What does a visible focus indicator tell a keyboard user?', correct: 'Which interactive element will receive the next keyboard action.', distractors: ['Which element is currently selected by a pointer.', 'Whether the page has passed a full accessibility audit.', 'Which text is the most important on the page.'], explanation: 'Visible focus communicates the current keyboard position.' },
    { level: 'Advanced', type: 'scenario', section: 'Keyboard access', prompt: 'Pressing Tab moves into a widget but no keyboard command can move focus out. What is this commonly called?', correct: 'A keyboard trap.', distractors: ['A landmark skip.', 'A status message.', 'A focus indicator.'], explanation: 'A keyboard trap prevents keyboard users from moving focus away from a component.' },
    { level: 'Intermediate', type: 'application', section: 'Pointer input', prompt: 'A user accidentally activates a destructive action by pressing and releasing a pointer. Which behavior can reduce this risk?', correct: 'Allow the action to be canceled or confirm it before committing when appropriate.', distractors: ['Make cancellation possible only with a mouse.', 'Commit the action on pointer-down with no undo.', 'Hide the result of the action.'], explanation: 'WCAG pointer cancellation requirements reduce unintended activation and adverse consequences.' },
    { level: 'Foundational', type: 'concept', section: 'Input methods', prompt: 'Why should functionality generally not depend on a specific keystroke timing?', correct: 'Some users need more time or alternative ways to operate input.', distractors: ['Browsers cannot process timed input.', 'Timing is only relevant to color contrast.', 'All users enter keystrokes at the same speed.'], explanation: 'Avoiding unnecessary timing constraints supports users with varied motor and cognitive access needs.' },
    { level: 'Intermediate', type: 'scenario', section: 'Touch targets', prompt: 'A mobile interface places several tiny controls very close together. What is the most relevant concern?', correct: 'Users may have difficulty accurately activating a target, especially with limited dexterity.', distractors: ['Small controls improve screen-reader naming.', 'Touch targets are irrelevant to accessibility.', 'The controls must be removed from keyboard order.'], explanation: 'Target size and spacing can make pointer and touch activation more reliable.' }
  ]);

  add(1, 'Understandable interaction and robust implementation', 'wcag', [
    { level: 'Foundational', type: 'application', section: 'Labels and instructions', prompt: 'A required form field is indicated only by its red border. What should be added?', correct: 'A programmatically associated label and a textual indication that the field is required.', distractors: ['A second red border.', 'A tooltip available only on hover.', 'A sound with no visible or programmatic cue.'], explanation: 'Labels and instructions should communicate field purpose and requirements beyond color alone.' },
    { level: 'Intermediate', type: 'scenario', section: 'Error identification', prompt: 'After submission, a form reports “Something went wrong” but gives no field or correction. What should the team improve?', correct: 'Identify the affected input and explain the error and how to correct it.', distractors: ['Clear the form without notice.', 'Mark every field invalid.', 'Use color without a message.'], explanation: 'Textual, specific error identification helps users understand and correct input problems.' },
    { level: 'Foundational', type: 'concept', section: 'Predictable operation', prompt: 'What is one benefit of consistent navigation across pages?', correct: 'Users can more reliably predict where familiar controls and destinations are located.', distractors: ['It removes the need for headings.', 'It guarantees legal compliance in every jurisdiction.', 'It prevents the page from being zoomed.'], explanation: 'Consistent behavior and identification support predictable, understandable interaction.' },
    { level: 'Advanced', type: 'application', section: 'Programmatic semantics', prompt: 'Why is a native HTML button usually preferable to a clickable generic element?', correct: 'It provides built-in semantics, keyboard behavior, and state exposure that custom code would otherwise need to recreate.', distractors: ['Generic elements are forbidden in HTML.', 'Native buttons guarantee correct visual design.', 'A button automatically explains the action in every language.'], explanation: 'Native controls provide expected semantics and interaction behavior, reducing custom implementation risk.' },
    { level: 'Intermediate', type: 'scenario', section: 'Name, role, value', prompt: 'A custom toggle visually changes state, but assistive technology still reports it as a plain text label. What is missing?', correct: 'Programmatic semantics and state that expose the control as an interactive toggle.', distractors: ['A larger logo.', 'A page-level transcript.', 'A different URL path.'], explanation: 'Interactive components need an accessible name, role, and current value or state.' },
    { level: 'Foundational', type: 'application', section: 'Page structure', prompt: 'What is the best use of HTML heading elements?', correct: 'Represent the logical hierarchy and organization of the content.', distractors: ['Choose font size without regard to meaning.', 'Create a heading for every sentence.', 'Replace labels on form controls.'], explanation: 'Semantic headings communicate document structure and support navigation.' },
    { level: 'Intermediate', type: 'concept', section: 'Robust implementation', prompt: 'What does it mean for a component’s role, name, and value to be programmatically determinable?', correct: 'Browsers and assistive technologies can identify what it is, what it is called, and its current state or value.', distractors: ['The component uses a particular brand color.', 'The component has a visual label but no code semantics.', 'The component is automatically legally certified.'], explanation: 'Programmatically determinable information supports interoperability with user agents and assistive technologies.' },
    { level: 'Advanced', type: 'scenario', section: 'Robust implementation', prompt: 'A custom widget works with a mouse but has no keyboard behavior or exposed state. Which repair strategy is strongest?', correct: 'Use a suitable native HTML control or implement the complete expected semantics and keyboard interaction.', distractors: ['Add an icon and leave behavior unchanged.', 'Hide it from assistive technology.', 'Test it only at one screen size.'], explanation: 'Robust custom widgets must implement semantics and interaction patterns; using native controls is often safer.' },
    { level: 'Foundational', type: 'concept', section: 'Page structure', prompt: 'What purpose does a page language declaration serve?', correct: 'It helps user agents identify the language used to present and process text.', distractors: ['It translates the page automatically.', 'It sets the page’s contrast ratio.', 'It replaces captions on video.'], explanation: 'Programmatically identifying the page language helps browsers and assistive technologies present content appropriately.' },
    { level: 'Intermediate', type: 'application', section: 'Consistent identification', prompt: 'Two buttons perform the same action but have different labels on nearby pages. What should a team consider?', correct: 'Use consistent identification for components that have the same functionality.', distractors: ['Change the labels on every visit.', 'Remove the accessible names.', 'Make one button keyboard-inaccessible.'], explanation: 'Consistent labels and identification make repeated controls easier to recognize and operate.' }
  ]);

  add(2, 'Standards and international frameworks', 'crpd', [
    { level: 'Foundational', type: 'concept', section: 'International frameworks', prompt: 'What kind of instrument is the Convention on the Rights of Persons with Disabilities (CRPD)?', correct: 'An international human-rights treaty concerning the rights of persons with disabilities.', distractors: ['A browser testing tool.', 'A U.S. state building code.', 'A web conformance certification.'], explanation: 'The CRPD is a United Nations treaty that promotes and protects the rights and participation of persons with disabilities.' },
    { level: 'Intermediate', type: 'application', section: 'Standards and law', prompt: 'A team follows WCAG for a public website. What can it safely conclude about legal compliance?', correct: 'WCAG can inform accessibility work, but legal obligations depend on the applicable jurisdiction and context.', distractors: ['WCAG automatically resolves every legal issue worldwide.', 'WCAG replaces all disability-rights legislation.', 'Any WCAG conformance claim guarantees no discrimination.'], explanation: 'Technical standards and legal requirements are related but not interchangeable; jurisdiction-specific analysis matters.' },
    { level: 'Foundational', type: 'concept', section: 'Standards and law', prompt: 'Which organization develops the Web Content Accessibility Guidelines?', correct: 'The World Wide Web Consortium (W3C), through its Web Accessibility Initiative.', distractors: ['The United Nations Security Council.', 'The U.S. Department of Justice alone.', 'A single commercial browser vendor.'], explanation: 'W3C’s Web Accessibility Initiative develops web accessibility standards and guidance, including WCAG.' },
    { level: 'Intermediate', type: 'scenario', section: 'International frameworks', prompt: 'A global organization operates in countries with different accessibility laws. What is the most responsible approach?', correct: 'Identify the applicable legal requirements in each jurisdiction and use technical standards as relevant guidance.', distractors: ['Assume the law of its headquarters applies everywhere.', 'Choose the least restrictive requirement for all countries.', 'Ignore local implementation and enforcement differences.'], explanation: 'Requirements vary across jurisdictions and sectors; teams should assess obligations in each relevant context.' },
    { level: 'Advanced', type: 'concept', section: 'Standards and law', prompt: 'Why is an accessibility technical standard not identical to a disability-rights statute?', correct: 'A technical standard defines testable or technical requirements, while statutes establish legal duties and rights in a jurisdiction.', distractors: ['Technical standards are always private contracts.', 'Statutes are only design examples.', 'The terms are interchangeable in every legal system.'], explanation: 'Standards and laws serve different roles; standards may be incorporated or referenced by law but are not the same instrument.' }
  ]);

  add(2, 'U.S. laws and ICT requirements', 'ada', [
    { level: 'Foundational', type: 'concept', section: 'Americans with Disabilities Act', prompt: 'What is the Americans with Disabilities Act (ADA)?', correct: 'A U.S. federal civil-rights law prohibiting disability discrimination in covered contexts.', distractors: ['A global web content standard.', 'A WCAG conformance level.', 'A certification for assistive technology.'], explanation: 'The ADA is a U.S. civil-rights statute; its application depends on the covered context and legal interpretation.' },
    { level: 'Intermediate', type: 'application', section: 'Section 508', prompt: 'What does Section 508 primarily address?', correct: 'Accessibility of covered information and communication technology used, developed, maintained, or procured by U.S. federal agencies.', distractors: ['A universal private-sector law in every country.', 'Requirements for caption timing only.', 'The international WCAG conformance levels.'], explanation: 'Section 508 is a U.S. federal ICT accessibility requirement; scope depends on the statutory and regulatory context.' },
    { level: 'Advanced', type: 'scenario', section: 'Americans with Disabilities Act', prompt: 'A U.S. business asks whether a specific website is covered by the ADA. What response is most accurate?', correct: 'Coverage is a legal question that depends on the entity, context, and applicable interpretation; consult qualified legal guidance.', distractors: ['Every website is covered identically by one technical clause.', 'WCAG alone determines the entire legal analysis.', 'The ADA applies only to software installed by federal agencies.'], explanation: 'The ADA’s application is context dependent; a technical accessibility standard is not a complete substitute for legal analysis.' },
    { level: 'Foundational', type: 'concept', section: 'Section 504', prompt: 'Section 504 of the Rehabilitation Act generally prohibits disability discrimination in which setting?', correct: 'Programs or activities receiving federal financial assistance and certain federal contexts.', distractors: ['Only commercial websites outside the United States.', 'Only private homes.', 'Every international service regardless of jurisdiction.'], explanation: 'Section 504 addresses covered programs and activities receiving federal financial assistance and specified federal contexts.' },
    { level: 'Intermediate', type: 'application', section: 'Section 508', prompt: 'A federal team is buying an ICT product. Which procurement action best supports Section 508 responsibilities?', correct: 'Evaluate accessibility requirements and evidence during procurement and address identified gaps.', distractors: ['Wait until the product is in use before asking about accessibility.', 'Assume a vendor’s marketing statement establishes conformance.', 'Exclude users who rely on assistive technology.'], explanation: 'Accessibility requirements and evaluation belong in covered ICT procurement and lifecycle processes.' }
  ]);

  add(2, 'Accessibility governance and management', 'iaap', [
    { level: 'Foundational', type: 'concept', section: 'Accessibility program management', prompt: 'Which combination best supports a sustainable organizational accessibility program?', correct: 'Leadership commitment, clear roles, resources, goals, and recurring processes.', distractors: ['One audit with no owner or follow-up.', 'A statement that transfers responsibility to users.', 'A single tool report treated as the complete program.'], explanation: 'Sustainable programs embed ownership, resources, goals, and repeatable accessibility work.' },
    { level: 'Intermediate', type: 'scenario', section: 'Accessibility program management', prompt: 'An audit identifies a severe barrier in a service already used by customers. What should the team do?', correct: 'Prioritize remediation, provide an accessible support path where feasible, assign ownership, and verify the fix.', distractors: ['Wait for a complete redesign before offering help.', 'Close the issue because testing has finished.', 'Remove the service without telling affected users.'], explanation: 'Responsible remediation addresses impact, provides interim support where possible, and tracks an issue through verification.' },
    { level: 'Foundational', type: 'application', section: 'Accessibility evaluation', prompt: 'What can automated accessibility checking reliably do?', correct: 'Detect some machine-checkable issues, while leaving other barriers for human evaluation.', distractors: ['Prove that every user can complete every task.', 'Determine whether every image alternative is meaningful.', 'Replace testing with disabled users and assistive technologies.'], explanation: 'Automated tools can identify some failures but cannot assess every content, interaction, or lived-experience issue.' },
    { level: 'Intermediate', type: 'scenario', section: 'Procurement and conformance reports', prompt: 'A vendor provides a completed VPAT. What is the most accurate interpretation?', correct: 'It is a vendor-reported accessibility conformance report that should be reviewed for scope and evidence.', distractors: ['It is an independent certificate guaranteeing accessibility.', 'It proves all user tasks work in all configurations.', 'It removes the purchaser’s need to evaluate the product.'], explanation: 'A VPAT is a template for reporting conformance; the resulting ACR is not itself a certification.' }
  ]);

  window.CPACC_EXPANDED_QUESTIONS = questions;
  window.CPACC_SOURCE_REFERENCES = sources;
}());
